library(aroma.affymetrix);
setwd("//workfolder")
log <- Arguments$getVerbose(-4);
timestampOn(log);
dataSetName <- "Affymetrix_2006-TumorNormal";
chipTypes <- c("Mapping250K_Nsp", "Mapping250K_Sty");
